#!/usr/bin/env node
// Generates src/data/sites/<site>/assets.ts (local paths + intrinsic sizes only) and the
// research ASSET_MANIFEST.json from the downloader's raw manifest. Runtime code never sees
// a source URL: provenance stays in docs/research.
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), "..");
const SITE = "norda-framer-website-3f1ea7cb";
const raw = JSON.parse(fs.readFileSync(path.join(ROOT, "docs/research", SITE, "ASSET_MANIFEST.raw.json"), "utf8"));

const lines = [
  "// Generated by scripts/generate-asset-map-norda-framer-website-3f1ea7cb.mjs — do not edit by hand.",
  'import type { MediaAsset } from "@/types/sites/norda-framer-website-3f1ea7cb";',
  "",
  "export const assets = {",
];
for (const a of raw.filter((a) => a.status === "ok" && a.kind !== "font").sort((x, y) => x.id.localeCompare(y.id))) {
  const dims = a.intrinsicWidth ? `, width: ${a.intrinsicWidth}, height: ${a.intrinsicHeight}` : "";
  lines.push(`  ${JSON.stringify(a.id)}: { src: ${JSON.stringify(a.localPath)}, kind: ${JSON.stringify(a.kind)}${dims} },`);
}
lines.push("} as const satisfies Record<string, MediaAsset>;", "", "export type AssetId = keyof typeof assets;", "");
const out = path.join(ROOT, "src/data/sites", SITE, "assets.ts");
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join("\n"));

const manifest = raw.map((a) => ({
  id: a.id,
  kind: a.kind,
  sourceUrl: a.sourceUrl,
  localPath: a.localPath,
  sha256: a.sha256 ?? null,
  mimeType: a.mimeType ?? null,
  bytes: a.bytes ?? null,
  intrinsicWidth: a.intrinsicWidth ?? null,
  intrinsicHeight: a.intrinsicHeight ?? null,
  durationIfMedia: a.kind === "video" ? "UNKNOWN (not probed; loops in reference)" : null,
  usageRoutes: a.usageRoutes,
  usageComponents: [],
  cropOrFocalPoint: "object-fit: cover, object-position: 50% 50% (MEASURED on reference <img> elements)",
  fontFamilyAndWeightIfApplicable: a.fontFamilyAndWeight ?? null,
  status: a.status,
  notes: a.notes ?? "",
}));
fs.writeFileSync(path.join(ROOT, "docs/research", SITE, "ASSET_MANIFEST.json"), JSON.stringify(manifest, null, 2));
console.log(`wrote ${out} (${manifest.length} manifest entries)`);
